"""Reconcile Phase 2.5 requirements against corrected bounded evidence."""
from pathlib import Path
from fractions import Fraction as F
import json, hashlib, collections

P = Path('docs/planning')
B = P / 'campaign3-history-universe-rev1'
O = P / 'campaign3-history-phase25-brief-rev1'
source = next(Path('reference').glob('*Phase 2.5*Brief.md')).as_posix()

def load(p): return json.loads(Path(p).read_text(encoding='utf-8-sig'))
def ref(p): return dict(path=Path(p).as_posix(), sha256=hashlib.sha256(Path(p).read_bytes()).hexdigest())
def save(p, v):
    if p.exists(): assert load(p) == v, p
    else: p.write_text(json.dumps(v, ensure_ascii=False, indent=2)+'\n', encoding='utf-8', newline='\n')

groups = [(1, 64, 'HISTORICAL FINDINGS', 'Semantic footprint competes for association row capacity; equal tags are not passive metadata. Clipped regulatory delta is not complete efficacy evidence. These motivate preserved salience/censoring controls, not a universal association or inference law.'), (65, 156, 'RESEARCH QUESTIONS', 'General salience and efficacy/reward separation are research questions. General governed event rules need not hand-author per-event weights, but authored semantics are not learned recognition. Vivarium implementation cost does not decide psychological necessity; findings inform later distillation.'), (157, 248, 'BOUNDARY INTENT / LATER CORRECTION', 'World, perception, encoding and learning must stay distinct. Historical SemanticExperience as post-salience envelope differs from current immutable pre-recognition envelope and typed consumers. Availability alone is not evidence admission. Earlier actual truth-side provenance/direct Applied fields remain restricted controls, not safe modern ports.'), (249, 347, 'CANDIDATE CATEGORY / ROLE LAWS', 'Category and role factors are authored priors; category must not alone prevent a causal object becoming salient. Role examples are not learned causal inference. Later EventRole/CausalRole and zero-or-many analytical roles supersede a universal one-role token. Illustrative ranking is not empirical parameter evidence.'), (348, 458, 'PERCEPTION / NEED / SURPRISE', 'Binary perception and registration are historical controls; missing perception forces zero encoding. General feature/modality evidence remains finer-grained. Need relevance and attribution require admitted operands. Raw absolute r-mu surprise is a point-evidence rule; later evidence-aware bound surprise can be zero despite nonzero numerical difference. Betrayal examples are qualitative hypotheses, not whole behavioral qualification.'), (459, 543, 'RETAINED SALIENCE COMPARATORS', 'Multiplicative category/role/attention times1+Need and1+surprise is explicitly a candidate. A independent, B shared and C hybrid remain distinct; B needs a positive denominator, and nonnegative raw inputs for stated bounds. Independent encoding does not remove downstream graph row competition. No universal limited-attention law is selected.'), (544, 642, 'BOUNDED SIX-SCENARIO CRITERIA', 'A-F and eight success criteria exercise governed ordinary/conflict/object/location/surprise/perception cases. They do not demonstrate arbitrary emergent causal recognition, natural attention or absence of all tag-count effects. The integration test proves wiring; it does not abolish finite association budget.'), (643, 764, 'RETAINED PHYSICAL / EVIDENCE / REWARD DISTINCTIONS', 'Capacity/Applied/Overflow is objective clamping math; it does not determine what a character observes. Signed effect and negative overflow magnitude conventions must be explicit. Efficacy evidence differs from realized utility, and possible hedonic reward is independent. This separation survives later biological integration.'), (765, 884, 'CENSORED CANDIDATES / UNMET STRONGER REQUEST', 'The brief asks for explicit inequality evidence rather than treating it as a point, and compares naive/censored/censored-plus-overflow-reward. Historical correction rejects compatible and equality bounds but accepted bounds still use the point-weighted mean and full rho credit: the stronger exact-likelihood requirement is not fully met. Four cases establish bounded sufficiency, not Bayesian posterior correctness. Overflow reward remained diagnostic/deferred; it is not an admitted character signal.'), (885, 979, 'EFFICACY / UTILITY EXPERIMENT SCOPE', 'Five-level sweep and repeated two-timeline counterfactual are distinct. A fresh-prior sweep cannot establish general learned-efficacy equality. Corrected counterfactual reduces divergence about48 percent rather than17 percent, but still undershoots true efficacy. Preserving known estimates under weak bounds is not recovering unobserved effect magnitude.'), (980, 1079, 'REWARD / SATURATION INTERACTION', 'Deferred reward is not demonstrated unnecessary in all later domains. Four interaction controls preserve admitted Applied/kind equivalence while Overflow changes, and separate Need relevance from evidence-aware surprise. Positive category/role/attention can leave encoding positive at total saturation. Candidate pipeline is not current scheduler topology; no omniscient saturation or reward shortcut follows.'), (1080, 1210, 'TRACE / MATHEMATICAL PROOF BURDEN', 'Truth trace can show potential effect without granting evidence access. Bounds and decomposition require explicit domains. The never-exact-uncensored-measurement obligation is stronger than the actual accepted-bound approximation; preservation must state that gap rather than relabel it satisfied. Determinism and complete evidence citations do not establish psychological validity.'), (1211, 1307, 'HISTORICAL DELIVERABLE / GATE SCOPE', 'Proposed deliverables are not all completed findings. Phase closure is bounded to recorded tests and deferred Reward. Censoring protects an established estimate but does not eliminate every saturation artifact; no universal emergent encoding or computational scaling claim. Current history/corpus/native gates remain independent.'), (1308, 1391, 'CLASSIFICATION / PRESERVATION', 'Derived/requires/deferred are requested research dispositions, not conclusions. Objective effect, regulatory delta, learned efficacy, salience and possible reward remain distinct. Later biological pleasure/relief/harm signals do not retroactively validate Applied+kOverflow. Preserve competitors and reopen broader posterior, attention and reward claims only under their material triggers.')]
entries={e['path']:e for e in load(B/'manifest.json')['entries']}
assert ref(source)['sha256']==entries[source]['sha256']
assert len(Path(source).read_text(encoding='utf-8').splitlines())==1391
chainpaths=['CHARACTER_ARCHITECTURE.md','CharacterLab — Ideal Character Research Program Brief.md',str(P/'REFERENCE_MECHANISM_LEDGER.md'),str(P/'CAMPAIGN3_HISTORY_MECHANISMS_CHECKPOINT.md'),str(P/'CAMPAIGN3_HISTORY_VALUES_ADDITION_CHECKPOINT.md'),str(P/'CAMPAIGN3_BELIEF_QUALIFICATION.md'),str(P/'CAMPAIGN3_HISTORY_REFERENCE_README_CHECKPOINT.md'),str(P/'CAMPAIGN3_HISTORY_BIOLOGY_SOURCES_CHECKPOINT.md'),str(P/'CAMPAIGN3_HISTORY_DEFINING_PUBLIC_CHECKPOINT.md'), 'reference/RESEARCH.md', 'reference/src/model/estimate.ts', str(P/'campaign3-history-research-censoring-rev1/review.json'), str(P/'campaign3-history-research-salience-rev1/review.json'), str(P/'campaign3-history-reference-readme-rev2/tests.json')]
chain=[ref(p) for p in chainpaths]
rows=[]
with (B/'units.jsonl').open(encoding='utf-8') as f:
    for line in f:
        u=json.loads(line)
        if u['source']!=source: continue
        a,b=u['location']['startLine'],u['location']['endLine']
        selected=[g for g in groups if g[0]<=a<=b<=g[1]]
        assert len(selected)==1,(a,b)
        g=selected[0]
        rows.append(dict(occurrenceId=u['id'],source=source,sourceSha256=u['sourceSha256'],location=u['location'],text=u['text'],role=g[2],judgment=g[3]))
assert len(rows)==len({r['occurrenceId'] for r in rows})
O.mkdir(exist_ok=True)

prior=F(1,20);bound=F(1,10);tau=F(50);rho=F(1)
mean=(tau*prior+rho*bound)/(tau+rho)
assert prior<mean<bound and tau+rho==51
save(O/'arithmetic-check.json',dict(status='PASS: ACCEPTED BOUND IS NOT A HARD LOWER-BOUND POSTERIOR',priorMean=str(prior),lowerBound=str(bound),priorPrecision=str(tau),observationPrecision=str(rho),updatedMean=str(mean),updatedPrecision=str(tau+rho),finding='The historical gated point-weighted update moves toward an inconsistent lower bound, remains below it, and credits full rho. This is its documented approximation, not a projection or exact censored posterior.',scope='Exact pre-quantization historical formula. No new runtime experiment.',checker=ref(__file__)))
obs=['RO-C3-004','RO-C3-008','RO-C3-010','RO-C3-019','RO-C3-020','RO-C3-021']
role=dict(**ref(source),role='HISTORICAL PHASE2.5 REQUIREMENTS / CANDIDATES',judgment='All1391 lines reviewed. Retain finite salience and censored-learning findings, failed precision rule and corrected scope. Accepted bounds still receive point-like precision: stronger original requirement not fully satisfied. Overflow reward deferred, not proved unnecessary.',acceptanceChain=chain+[ref(O/'arithmetic-check.json')])
review=dict(status='WHOLE PHASE2.5 BRIEF RECONCILED; HQ011 OPEN',sourceRoles=[role],reviewedLineRanges=[[1,1391]],rows=rows,scopeFindings=[dict(startLine=a,endLine=b,role=r,judgment=j) for a,b,r,j in groups],obligations=obs,limits=['No new runtime test or full historical suite rerun.','Remaining four historical briefs need separate review.','Formula pin, legacy log and GA provenance remain open.'])
save(O/'review.json',review)
save(O/'check.json',dict(status='PASS; HQ011 OPEN',sources=1,originalNarrativeOccurrences=len(rows),originalBackingOccurrences=0,sectionGroups=len(groups),checker=ref(__file__)))
v=load(P/'campaign3-history-source-roles-rev64/index.json');roles={r['path']:r for r in v['roleAssignments']}
assert source not in roles
roles[source]=dict(path=source,sha256=role['sha256'],category='WHOLE_PHASE25_BRIEF_REVIEWED',role=role['role'],scope=role['judgment'],evidence=[ref(O/'review.json')],acceptanceChain=role['acceptanceChain'])
v['version']='campaign3-history-source-roles/0.65';v['predecessor']=ref(P/'campaign3-history-source-roles-rev64/index.json')
v['roleAssignments']=[roles[p] for p in sorted(roles)];v['unassignedCandidatePaths']=sorted(set(entries)-set(roles));v['reviewedInputs'].append(ref(O/'review.json'))
v['originalNarrativeOrFindingOccurrences']+=len(rows);v['backingBreakdown']['phase25Brief']=0
v['rules'].append('REV65 adds whole Phase2.5 brief; finite salience/censoring and accepted-bound approximation preserved. Stronger exact-inequality requirement not silently qualified. Deferred overflow reward is not a native reward law.')
I=P/'campaign3-history-source-roles-rev65';I.mkdir(exist_ok=True);save(I/'index.json',v)
check=dict(status=v['status'],candidateFiles=len(entries),assignedSources=len(roles),unassignedWithinThisIndex=len(v['unassignedCandidatePaths']),originalNarrativeOrFindingOccurrences=v['originalNarrativeOrFindingOccurrences'],originalBackingOccurrences=v['originalBackingFieldOccurrences'],explicitArchivesOutsideCensus=len(v['explicitBackingOutsideProseManifest']),indexSha256=ref(I/'index.json')['sha256'],checkerSha256=ref(__file__)['sha256'])
save(I/'check.json',check);print(json.dumps(check))
